import java.util.Arrays;

public class Main {
  public static void main(String[] args) {
    int[] arr = {1, 2, 3, 4, 5};
    // Java requiere usar clone() o copyOf() para copias duras
    int[] x = arr.clone();

    arr[0] = 42;
    System.out.println(Arrays.toString(arr)); // [42, ...]
    System.out.println(Arrays.toString(x));   // [1, ...]
  }
}

import java.util.Arrays;

public class Main {
  public static void main(String[] args) {
    int[] arr = {1, 2, 3, 4, 5};
    // En Java, asignar variables siempre pasa por referencia (Vista)
    int[] x = arr;

    arr[0] = 42;
    System.out.println(Arrays.toString(arr)); // [42, ...]
    System.out.println(Arrays.toString(x));   // [42, ...]
  }
}
